D=/workspace/nox/c300_voice/voice2; mkdir -p $D
echo  | base64 -d > $D/ru_norm.py
echo  | base64 -d > $D/tts2_server.py
echo  | base64 -d > $D/test10.py
cd $D; export NOX_VOICE_MODELS=/workspace/nox/voice_models
nohup setsid nice -n 5 /workspace/nox/voice2_venv/bin/python tts2_server.py > /workspace/nox/svc/logs/tts2.log 2>&1 &
sleep 40; curl -s http://127.0.0.1:8095/health; echo
tail -5 /workspace/nox/svc/logs/tts2.log
nohup setsid /workspace/nox/voice2_venv/bin/python test10.py > /workspace/nox/svc/logs/tts2_test.log 2>&1 &
sleep 2; echo ok
